CREATE VIEW public.chart_entries_detailed AS
 SELECT ce.chart_week,
    ce.rank,
    ce.is_new,
    ce.weeks,
    ce.peak_pos,
    s.song_id,
    s.title AS song_title,
    a.artist_id,
    a.name AS artist_name,
    a.tag AS artist_genre,
    ce.title AS billboard_title,
    ce.artist AS billboard_artist
   FROM ((public.chart_entries ce
     LEFT JOIN public.songs s ON (((ce.song_id)::text = (s.song_id)::text)))
     LEFT JOIN public.artists a ON (((ce.artist_id)::text = (a.artist_id)::text)));


